#!/usr/bin/env bash
set -uo pipefail
export PATH="$HOME/.bun/bin:$PATH"
gbrain recall --query "gbrain install check" --json 2>/dev/null > /tmp/rec.json
python3 - <<'EOF'
import json
d=json.load(open('/tmp/rec.json'))
def walk(o):
    if isinstance(o,dict):
        if o.get('claim') and 'install check' in str(o.get('claim')):
            print({k:o.get(k) for k in ('fact_id','id','claim','subject','status')})
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
EOF
